    valor_spam = p_spam
    valor_ham = p_ham
    for palabra in palabras:
        valor_spam *= probabilidad_palabra(palabra, palabras_spam, spam)
        valor_ham *= probabilidad_palabra(palabra, palabras_ham, ham)
    if valor_spam > valor_ham:
        return 'SPAM'
    elif valor_ham > valor_spam:
        return 'HAM'
    else:
