def clasificar_mensaje_seguro(palabras):
    valor_spam = p_spam
    valor_ham = p_ham
    for palabra in palabras:
        if palabra in palabras_spam and palabra in palabras_ham:
            valor_spam *= probabilidad_palabra(palabra, palabras_spam, spam)
            valor_ham *= probabilidad_palabra(palabra, palabras_ham, ham)
        else:
            print('Aviso: no conozco la palabra', palabra)
    if valor_spam > valor_ham:
        return 'SPAM'
    elif valor_ham > valor_spam:
        return 'HAM'
    else:
        return 'EMPATE'

print(clasificar_mensaje_seguro(['oferta', 'exclusivo']))

